package com.bank.badge.service;

import com.bank.badge.model.Employee;
import java.util.List;
import java.util.Locale;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class BadgeService {
    private static final Logger log = Logger.getLogger(BadgeService.class.getName());

    public List<String> upperCaseNames(List<Employee> employees) {
        log.info(() -> "Converting " + employees.size() + " names to uppercase for badges");
        return employees.stream()
                .map(Employee::getName)
                // Locale.ROOT → deterministic uppercasing across regions.
                .map(name -> name.toUpperCase(Locale.ROOT))
                .collect(Collectors.toList());
    }
}
