package com.bank.badge;

import com.bank.badge.model.Employee;
import com.bank.badge.service.BadgeService;
import java.util.List;
import java.util.logging.Logger;

public class Main {
    private static final Logger log = Logger.getLogger(Main.class.getName());

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh"),
            new Employee("priya"),
            new Employee("Amit")
        );

        List<String> badges = new BadgeService().upperCaseNames(staff);
        log.info(() -> "Badge names: " + badges);
    }
}
